    private fun chapter1() = StoryChapter(
        number = 1, title = "The Arrival", titlePersian = "ورود",
        paragraphs = listOf(
            StoryParagraph("It was the autumn of nineteen forty-two, and Viktor Frankl was a young doctor in Vienna, a specialist in neurology and psychiatry, a man who had built a life of meaning and purpose and love.", "پاییز هزار و نهصد و چهل و دو بود و ویکتور فرانکل پزشک جوانی در وین بود، متخصص عصب‌شناسی و روان‌پزشکی، مردی که زندگی‌ای از معنا و هدف و عشق ساخته بود."),
            StoryParagraph("He had a wife, a woman he loved more than anything in the world. He had a career, a career that was just beginning to flourish. He had a book, a book that would establish his reputation. He had everything, and then he had nothing.", "همسری داشت، زنی که بیشتر از هر چیزی در جهان دوستش داشت. حرفه‌ای داشت، حرفه‌ای که تازه شروع به شکوفایی کرده بود. کتابی داشت، کتابی که شهرتش را تثبیت می‌کرد. همه چیز داشت، و سپس هیچ نداشت."),
            StoryParagraph("The Nazis came, came for him, came for his wife, came for his parents, came for every Jew in Vienna, came to destroy everything that he had built and everything that he was.", "نازی‌ها آمدند، برایش آمدند، برای همسرش آمدند، برای والدینش آمدند، برای هر یهودی در وین آمدند، آمدند تا هر چیزی که ساخته بود و هر چیزی که بود را نابود کنند."),
            StoryParagraph("He was arrested, arrested with his wife, arrested with his parents, arrested and taken to a concentration camp, arrested and stripped of everything that had made him who he was, arrested and reduced to a number.", "او دستگیر شد، با همسرش دستگیر شد، با والدینش دستگیر شد، دستگیر شد و به اردوگاه کار اجباری برده شد، دستگیر شد و از هر چیزی که او را آنچه بود ساخته بود برهنه شد، دستگیر شد و به شماره‌ای تقلیل یافت."),
            StoryParagraph("The camp was called Theresienstadt, was a transit camp, was a place of waiting, was a place from which people were sent to other camps, to worse camps, to camps from which no one returned.", "اردوگاه ترزینشتات نامیده می‌شد، اردوگاهی عبوری بود، جایی برای انتظار بود، جایی بود که مردم از آن به اردوگاه‌های دیگر فرستاده می‌شدند، به اردوگاه‌های بدتر، به اردوگاه‌هایی که هیچ‌کس از آن‌ها بازنمی‌گشت."),
            StoryParagraph("Frankl arrived at the camp and was stripped of everything: his clothes, his possessions, his name, his hair, his dignity. He was given a uniform, a number, a place in a barrack, and nothing else.", "فرانکل به اردوگاه رسید و از هر چیزی برهنه شد: لباس‌هایش، دارایی‌هایش، نامش، موهایش، کرامتش. یونیفورم، شماره، جایی در پادگان و هیچ چیز دیگری به او داده شد."),
            StoryParagraph("He was no longer Viktor Frankl, the doctor, the professor, the husband, the son. He was now prisoner number eleven-nine-one-o-four, a number, a thing, an object to be used and then discarded.", "او دیگر ویکتور فرانکل نبود، دکتر، استاد، شوهر، پسر. او اکنون زندانی شماره یازده نه یک صفر چهار بود، شماره‌ای، چیزی، شیئی که به کار گرفته می‌شد و سپس دور انداخته می‌شد."),
            StoryParagraph("And yet, in that moment of complete destruction, something remained. Something that the Nazis could not take. Something that no one could take. Something that was his alone, that was the core of his being, that was the essence of his humanity.", "و با این حال، در آن لحظه نابودی کامل، چیزی باقی ماند. چیزی که نازی‌ها نمی‌توانستند بگیرند. چیزی که هیچ‌کس نمی‌توانست بگیرد. چیزی که تنها مال او بود، هسته وجودش بود، ذات انسانیتش بود."),
            StoryParagraph("This something was the freedom to choose his response, the freedom to decide how he would face this situation, the freedom to find meaning even in the midst of meaninglessness, the freedom that no prison could take away.", "این چیز آزادی انتخاب پاسخش بود، آزادی تصمیم گرفتن درباره چگونگی رویارویی با این وضعیت، آزادی یافتن معنا حتی در میان بی‌معنایی، آزادی‌ای که هیچ زندانی نمی‌توانست بگیرد."),
            StoryParagraph("Frankl realized, in that moment, that everything could be taken from a human being except one thing: the last of the human freedoms, the freedom to choose one's attitude in any given set of circumstances, the freedom to choose one's own way.", "فرانکل در آن لحظه فهمید که هر چیزی می‌تواند از یک انسان گرفته شود جز یک چیز: آخرین آزادی‌های انسانی، آزادی انتخاب نگرش در هر مجموعه شرایط، آزادی انتخاب راه خویش."),
            StoryParagraph("And with this realization, something changed, something shifted, something opened. He was still a prisoner, still a number, still a thing to be used. But he was also, in some mysterious way, still free.", "و با این درک، چیزی تغییر کرد، چیزی جابه‌جا شد، چیزی باز شد. او هنوز زندانی بود، هنوز شماره‌ای، هنوز چیزی که به کار گرفته می‌شد. اما او همچنین، به شکلی رمزآلود، هنوز آزاد بود."),
            StoryParagraph("The camp was a place of death, a place of suffering, a place of horror that no words can describe, a place where human beings were reduced to animals, to machines, to nothing.", "اردوگاه جایی از مرگ بود، جایی از رنج، جایی از وحشتی که هیچ کلمه‌ای نمی‌تواند توصیفش کند، جایی که انسان‌ها به حیوانات تقلیل می‌یافتند، به ماشین‌ها، به هیچ."),
            StoryParagraph("And yet, in that place of death, Frankl observed something remarkable: some prisoners survived, some prisoners died, and the difference was not always physical, was not always material, was not always explainable in ordinary terms.", "و با این حال، در آن جای مرگ، فرانکل چیزی قابل توجه مشاهده کرد: برخی زندانیان زنده می‌ماندند، برخی می‌مردند، و تفاوت همیشه فیزیکی نبود، همیشه مادی نبود، همیشه به زبان معمولی قابل توضیح نبود."),
            StoryParagraph("Those who survived, Frankl noticed, were not always the strongest, were not always the healthiest, were not always the luckiest. Those who survived were those who had a reason to survive, a meaning to live for, a purpose that kept them going.", "کسانی که زنده می‌ماندند، فرانکل متوجه شد، همیشه قوی‌ترین نبودند، همیشه سالم‌ترین نبودند، همیشه خوش‌شانس‌ترین نبودند. کسانی که زنده می‌ماندند کسانی بودند که دلیلی برای زنده ماندن داشتند، معنایی برای زندگی کردن، هدفی که به پیش می‌راندشان."),
            StoryParagraph("Some survived for their families, some for their work, some for their faith, some for a person they loved, some for a task they had not completed, some for a promise they had made.", "برخی برای خانواده‌هایشان زنده ماندند، برخی برای کارشان، برخی برای ایمانشان، برخی برای کسی که دوستش داشتند، برخی برای کاری که تمام نکرده بودند، برخی برای وعده‌ای که داده بودند."),
            StoryParagraph("And this, Frankl realized, was the key to survival, was the secret of the camp, was the truth that the Nazis could not take away: those who have a why to live can bear almost any how.", "و این، فرانکل فهمید، کلید بقا بود، راز اردوگاه بود، حقیقتی بود که نازی‌ها نمی‌توانستند بگیرند: کسانی که چرایی‌ای برای زندگی دارند می‌توانند تقریباً هر چگونگی‌ای را تحمل کنند."),
            StoryParagraph("Nietzsche had said this, had written this, had known this. But Frankl learned it in the camp, learned it in his own flesh, learned it in the flesh of the men who died and the men who survived.", "نیچه این را گفته بود، این را نوشته بود، این را می‌دانست. اما فرانکل آن را در اردوگاه آموخت، در گوشت خودش، در گوشت مردانی که مردند و مردانی که زنده ماندند."),
            StoryParagraph("And so began his search for meaning, began in the worst place on earth, began in a place designed to destroy meaning, began in a place where meaning was the only thing that could save you.", "و اینگونه جستجویش برای معنا آغاز شد، در بدترین جای زمین آغاز شد، در جایی که برای نابودی معنا طراحی شده بود آغاز شد، در جایی که معنا تنها چیزی بود که می‌توانست نجاتت دهد."),
            StoryParagraph("For in the camp, in the midst of hell, in the presence of death, Frankl found what he had been looking for all along: the truth about human existence, the secret of human survival, the meaning of human life.", "زیرا در اردوگاه، در میان جهنم، در حضور مرگ، فرانکل چیزی را یافت که تمام مدت دنبالش بود: حقیقت درباره هستی انسانی، راز بقای انسانی، معنای زندگی انسانی."),
            StoryParagraph("And so ended the first part of the story of Man's Search for Meaning, with the arrival at the camp, with the stripping of everything, with the discovery that something remained, something that no one could take.", "و اینگونه بخش نخست داستان انسان در جستجوی معنا با ورود به اردوگاه، با برهنه شدن از همه چیز، با کشف اینکه چیزی باقی ماند، چیزی که هیچ‌کس نمی‌توانست بگیرد، به پایان رسید."),
            StoryParagraph("For the story of Frankl was not merely the story of a man, not merely the story of a camp, not merely the story of a time. It was the story of humanity itself, of the human capacity for suffering and for survival, for despair and for hope.", "زیرا داستان فرانکل تنها داستان یک مرد نبود، تنها داستان یک اردوگاه نبود، تنها داستان یک زمان نبود. داستان خود بشریت بود، درباره توانایی انسانی برای رنج و بقا، برای ناامیدی و امید."),
            StoryParagraph("And so the story began, and so the story continued, and so the story would end, with the discovery that meaning is not given but found, not received but created, not imposed but chosen.", "و اینگونه داستان آغاز شد و اینگونه ادامه یافت و اینگونه پایان می‌یافت، با کشف اینکه معنا داده نمی‌شود بلکه یافته می‌شود، نه دریافت می‌شود بلکه آفریده می‌شود، نه تحمیل می‌شود بلکه برگزیده می‌شود."),
            StoryParagraph("The camp was a school, Frankl would later say, was the hardest school in the world, was a school that taught the deepest lessons, was a school from which no one graduated unscathed.", "اردوگاه مدرسه بود، فرانکل بعدها می‌گفت، سخت‌ترین مدرسه جهان بود، مدرسه‌ای بود که عمیق‌ترین درس‌ها را می‌آموخت، مدرسه‌ای بود که هیچ‌کس از آن بدون زخم فارغ‌التحصیل نمی‌شد."),
            StoryParagraph("And so ended the first part of the story of Man's Search for Meaning, with the arrival at the camp, with the beginning of the search, with the discovery that would change everything.", "و اینگونه بخش نخست داستان انسان در جستجوی معنا با ورود به اردوگاه، با آغاز جستجو، با کشفی که همه چیز را تغییر می‌داد، به پایان رسید."),
            StoryParagraph("The search had begun, and it would not end until Frankl had learned everything that the camp had to teach him, everything that suffering had to teach him, everything that life had to teach him.", "جستجو آغاز شده بود و پایان نمی‌یافت تا فرانکل هر چیزی که اردوگاه باید به او بیاموزد را آموخته بود، هر چیزی که رنج باید بیاموزد، هر چیزی که زندگی باید بیاموزد."),
            StoryParagraph("And so the story continued, as stories must, toward the lessons of the camp, toward the meaning that could be found in the worst of places, toward the truth that would set humanity free.", "و اینگونه داستان ادامه یافت، همان‌طور که داستان‌ها باید، به سمت درس‌های اردوگاه، به سمت معنایی که می‌شد در بدترین مکان‌ها یافت، به سمت حقیقتی که بشریت را آزاد می‌کرد."),
            StoryParagraph("And so ended the first part of the story of Man's Search for Meaning, with the stage set, with the players in place, with the search ready to be described.", "و اینگونه بخش نخست داستان انسان در جستجوی معنا با صحنه آماده، با بازیگران در جای خود، با جستجو آماده برای توصیف، به پایان رسید."),
            StoryParagraph("The young doctor stood in the yard of the camp, in his new uniform, with his new number, and he looked at the sky and wondered what would become of him, what would become of his wife, what would become of the world.", "دکتر جوان در حیاط اردوگاه ایستاد، در یونیفورم نوینش، با شماره نوینش، به آسمان نگاه کرد و حیران بود چه بر سرش می‌آید، چه بر سر همسرش می‌آید، چه بر سر جهان می‌آید."),
            StoryParagraph("But he did not know, could not know, would not know for years. All he knew was that he was alive, that he was still himself, that he had something that the Nazis could not take, and that this something would be his salvation.", "اما نمی‌دانست، نمی‌توانست بداند، سال‌ها نمی‌دانست. تنها می‌دانست زنده است، هنوز خودش است، چیزی دارد که نازی‌ها نمی‌توانند بگیرند، و این چیز نجاتش می‌داد."),
            StoryParagraph("And so the story began, and so the story continued, and so the story would end, with the discovery that even in the worst of places, in the worst of times, in the worst of conditions, meaning could be found.", "و اینگونه داستان آغاز شد و اینگونه ادامه یافت و اینگونه پایان می‌یافت، با کشف اینکه حتی در بدترین مکان‌ها، در بدترین زمان‌ها، در بدترین شرایط، معنا می‌تواند یافته شود."),
            StoryParagraph("And so ended the first part of the story of Man's Search for Meaning, with the arrival, with the stripping, with the discovery, with the beginning of a journey that would change the world.", "و اینگونه بخش نخست داستان انسان در جستجوی معنا با ورود، با برهنه شدن، با کشف، با آغاز سفری که جهان را تغییر می‌داد، به پایان رسید."),
            StoryParagraph("The journey had begun, the search had started, and nothing, not even the camp, not even the Nazis, not even death itself, could stop it now.", "سفر آغاز شده بود، جستجو شروع شده بود، و هیچ چیز، نه حتی اردوگاه، نه حتی نازی‌ها، نه حتی خود مرگ، نمی‌توانست اکنون متوقفش کند."),
            StoryParagraph("And so ended the first part of the story of Man's Search for Meaning, with the beginning of the search, with the beginning of the discovery, with the beginning of everything that was to come.", "و اینگونه بخش نخست داستان انسان در جستجوی معنا با آغاز جستجو، با آغاز کشف، با آغاز هر چیزی که می‌آمد، به پایان رسید."),
            StoryParagraph("The story continued, as all stories must, and the search continued, as all searches must, and the meaning would be found, as all meaning must be found, even in the darkest of places.", "داستان ادامه یافت، همان‌طور که همه داستان‌ها باید، و جستجو ادامه یافت، همان‌طور که همه جستجوها باید، و معنا یافته می‌شد، همان‌طور که همه معنا باید یافته شود، حتی در تاریک‌ترین مکان‌ها.")
        )
    )

    private fun chapter2() = StoryChapter(
        number = 2, title = "The Stages of Adjustment", titlePersian = "مراحل سازگاری",
        paragraphs = listOf(
            StoryParagraph("Frankl observed, in the camp, three stages of mental reaction to the horrors of imprisonment, three stages that every prisoner passed through, three stages that no one could avoid.", "فرانکل در اردوگاه سه مرحله واکنش ذهنی به وحشت‌های اسارت مشاهده کرد، سه مرحله‌ای که هر زندانی از آن می‌گذشت، سه مرحله‌ای که هیچ‌کس نمی‌توانست از آن اجتناب کند."),
            StoryParagraph("The first stage was shock, was the initial reaction to the horror, was the disbelief that such things could happen, was the refusal to accept the reality that was unfolding.", "مرحله نخست شوک بود، واکنش اولیه به وحشت، باور نکردن اینکه چنین چیزهایی می‌تواند اتفاق بیفتد، امتناع از پذیرش واقعیتی که باز می‌شد."),
            StoryParagraph("When Frankl arrived at the camp, when he saw the barracks, the guards, the other prisoners, when he heard the shouts and the barking and the screams, he could not believe what he was seeing.", "وقتی فرانکل به اردوگاه رسید، وقتی پادگان‌ها، نگهبانان، زندانیان دیگر را دید، وقتی فریادها و پارس‌ها و جیغ‌ها را شنید، نمی‌توانست باور کند چه می‌بیند."),
            StoryParagraph("This was not happening, not really, not to him. This was a nightmare, a dream, a hallucination. He would wake up, would return to his life, would find that none of this was real.", "این اتفاق نمی‌افتاد، واقعاً نه، نه برای او. این کابوس بود، رؤیا، توهم. بیدار می‌شد، به زندگی‌اش بازمی‌گشت، می‌فهمید هیچ‌کدام واقعی نیست."),
            StoryParagraph("But he did not wake up. The nightmare continued. The horror was real. And slowly, painfully, he began to accept what was happening, began to adjust, began to survive.", "اما بیدار نشد. کابوس ادامه یافت. وحشت واقعی بود. و به آرامی، به شکلی دردناک، شروع کرد به پذیرش آنچه می‌گذشت، شروع کرد به سازگار شدن، شروع کرد به زنده ماندن."),
            StoryParagraph("The second stage was apathy, was the emotional death that followed the shock, was the numbing of all feeling, was the loss of all reaction to the horror that surrounded him.", "مرحله دوم بی‌تفاوتی بود، مرگ عاطفی‌ای که پس از شوک می‌آمد، کرختی تمام احساسات، از دست دادن هر واکنشی به وحشتی که احاطه‌اش کرده بود."),
            StoryParagraph("The prisoners stopped reacting, stopped feeling, stopped caring. They saw death, saw suffering, saw horror, and they felt nothing. They had become, in a sense, dead inside.", "زندانیان از واکنش دست کشیدند، از احساس کردن، از اهمیت دادن. مرگ می‌دیدند، رنج، وحشت، و هیچ حس نمی‌کردند. به نوعی در درون مرده بودند."),
            StoryParagraph("This apathy was a defense, was a shield, was the only way to survive in a place where feeling would destroy you. It was not callousness, not indifference, not cruelty. It was survival.", "این بی‌تفاوتی دفاع بود، سپر بود، تنها راه بقا در جایی که احساس نابودت می‌کرد. بی‌رحمی نبود، بی‌تفاوتی نبود، ظلم نبود. بقا بود."),
            StoryParagraph("Frankl observed this in himself, observed this in the other prisoners, observed this in everyone. They stopped looking at the dead bodies, stopped mourning the dead, stopped even noticing that anyone had died.", "فرانکل این را در خودش مشاهده کرد، در زندانیان دیگر، در همه. از نگاه کردن به اجساد دست کشیدند، از عزاداری برای مرده‌ها، از حتی توجه کردن به اینکه کسی مرده بود."),
            StoryParagraph("But this apathy was not the end, was not the final state, was not the last stage. For some, at least, there was a third stage, a stage that came after the apathy, a stage that made survival possible.", "اما این بی‌تفاوتی پایان نبود، حالت نهایی نبود، مرحله آخر نبود. برای برخی، حداقل، مرحله سومی بود، مرحله‌ای که پس از بی‌تفاوتی می‌آمد، مرحله‌ای که بقا را ممکن می‌کرد."),
            StoryParagraph("The third stage was the discovery of meaning, was the finding of a reason to live, was the creation of a purpose in a place where purpose seemed impossible, was the affirmation of life in the presence of death.", "مرحله سوم کشف معنا بود، یافتن دلیلی برای زندگی، آفریدن هدفی در جایی که هدف ناممکن به نظر می‌رسید، تأیید زندگی در حضور مرگ."),
            StoryParagraph("Some prisoners found meaning in their families, in the thought of seeing their loved ones again, in the hope of a reunion that might never come but that kept them going.", "برخی زندانیان در خانواده‌هایشان معنا یافتند، در فکر دیدن دوباره عزیزانشان، در امید یک دیدار دوباره که شاید هرگز نمی‌آمد اما به پیش می‌راندشان."),
            StoryParagraph("Some found meaning in their work, in the thought of finishing something they had started, in the belief that their work would matter, that their life had a purpose beyond the camp.", "برخی در کارشان معنا یافتند، در فکر تمام کردن چیزی که شروع کرده بودند، در باور به اینکه کارشان اهمیت می‌داشت، که زندگی‌شان هدفی فراتر از اردوگاه داشت."),
            StoryParagraph("Some found meaning in their faith, in the belief that God had a plan, in the trust that there was a reason for their suffering, in the hope of something beyond this world.", "برخی در ایمانشان معنا یافتند، در باور به اینکه خدا نقشه‌ای داشت، در اعتماد به اینکه دلیلی برای رنجشان بود، در امید به چیزی فراتر از این جهان."),
            StoryParagraph("And some, like Frankl, found meaning in the search itself, in the very act of finding meaning, in the philosophical inquiry that kept their minds alive when their bodies were dying.", "و برخی، مثل فرانکل، در خود جستجو معنا یافتند، در همان عمل یافتن معنا، در پژوهش فلسفی‌ای که ذهنشان را زنده نگه می‌داشت وقتی بدنشان می‌مرد."),
            StoryParagraph("Frankl found meaning in the thought of his wife, in the image of her face, in the memory of her love. In the worst moments of the camp, he would close his eyes and see her, and the pain would become bearable.", "فرانکل در فکر همسرش معنا یافت، در تصویر چهره‌اش، در خاطره عشقش. در بدترین لحظه‌های اردوگاه، چشمانش را می‌بست و او را می‌دید، و درد قابل تحمل می‌شد."),
            StoryParagraph("He did not know if she was alive or dead, did not know if he would ever see her again, did not know if the love he felt was returned. But the love itself was enough, was meaning enough, was life enough.", "نمی‌دانست زنده است یا مرده، نمی‌دانست هرگز دوباره می‌بیندش، نمی‌دانست عشقی که حس می‌کرد متقابل است. اما خود عشق کافی بود، معنای کافی، زندگی کافی."),
            StoryParagraph("And this meaning, this love, this image, kept him alive. When others died of despair, he survived on love. When others gave up, he held on. When others lost hope, he found it in a memory.", "و این معنا، این عشق، این تصویر، او را زنده نگه داشت. وقتی دیگران از ناامیدی می‌مردند، او بر عشق زنده می‌ماند. وقتی دیگران تسلیم می‌شدند، او چنگ می‌زد. وقتی دیگران امید از دست می‌دادند، او در خاطره‌ای می‌یافتش."),
            StoryParagraph("And so Frankl learned the deepest lesson of the camp, learned it in his own flesh, learned it in the flesh of all who suffered around him: those who have a why to live can bear almost any how.", "و اینگونه فرانکل عمیق‌ترین درس اردوگاه را آموخت، در گوشت خودش آموخت، در گوشت همه کسانی که اطرافش رنج می‌کشیدند: کسانی که چرایی‌ای برای زندگی دارند می‌توانند تقریباً هر چگونگی‌ای را تحمل کنند."),
            StoryParagraph("And so ended the second part of the story of Man's Search for Meaning, with the three stages of adjustment, with the discovery of meaning, with the lesson that would change everything.", "و اینگونه بخش دوم داستان انسان در جستجوی معنا با سه مرحله سازگاری، با کشف معنا، با درسی که همه چیز را تغییر می‌داد، به پایان رسید."),
            StoryParagraph("For the camp was not merely a place of horror, not merely a place of death, not merely a place of suffering. The camp was also a place of discovery, a place of truth, a place where the deepest secrets of human existence were revealed.", "زیرا اردوگاه تنها جایی از وحشت نبود، تنها جایی از مرگ، تنها جایی از رنج. اردوگاه همچنین جایی از کشف بود، جایی از حقیقت، جایی که عمیق‌ترین رازهای هستی انسانی آشکار می‌شد."),
            StoryParagraph("And so the second part ended, and the third began, with the description of the inner life of the prisoner, with the analysis of the psychological states, with the understanding of the human capacity for survival.", "و اینگونه بخش دوم پایان یافت و سوم آغاز شد، با توصیف زندگی درونی زندانی، با تحلیل حالات روانی، با فهم توانایی انسانی برای بقا."),
            StoryParagraph("For the prisoner's inner life was rich, was complex, was full of meaning, even as his outer life was reduced to nothing. And it was this inner life that saved him, this inner life that kept him human.", "زیرا زندگی درونی زندانی غنی بود، پیچیده بود، پر از معنا، حتی وقتی زندگی بیرونی‌اش به هیچ تقلیل یافته بود. و این زندگی درونی بود که نجاتش می‌داد، این زندگی درونی بود که انسان نگهش می‌داشت."),
            StoryParagraph("And so the story continued, as stories must, toward the description of the inner life, toward the analysis of the psychological states, toward the understanding of the human capacity for meaning.", "و اینگونه داستان ادامه یافت، همان‌طور که داستان‌ها باید، به سمت توصیف زندگی درونی، به سمت تحلیل حالات روانی، به سمت فهم توانایی انسانی برای معنا."),
            StoryParagraph("And so ended the second part of the story of Man's Search for Meaning, with the three stages described, with the meaning discovered, with the third stage that would change everything.", "و اینگونه بخش دوم داستان انسان در جستجوی معنا با سه مرحله توصیف شده، با معنا کشف شده، با مرحله سومی که همه چیز را تغییر می‌داد، به پایان رسید."),
            StoryParagraph("The apathy was not the end, the shock was not the end, the horror was not the end. There was something beyond, something that made survival possible, something that made life worth living even in the camp.", "بی‌تفاوتی پایان نبود، شوک پایان نبود، وحشت پایان نبود. چیزی فراتر بود، چیزی که بقا را ممکن می‌کرد، چیزی که زندگی را ارزش زیستن می‌کرد حتی در اردوگاه."),
            StoryParagraph("And this something was meaning, was purpose, was love, was everything that the Nazis could not take, was everything that made life worth living even when life had nothing to offer.", "و این چیز معنا بود، هدف، عشق، هر چیزی که نازی‌ها نمی‌توانستند بگیرند، هر چیزی که زندگی را ارزش زیستن می‌کرد حتی وقتی زندگی چیزی برای عرضه نداشت."),
            StoryParagraph("And so the third stage came, and with it came hope, and with hope came survival, and with survival came the possibility of telling the story, of teaching the lesson, of helping others to find their own meaning.", "و اینگونه مرحله سوم آمد و با آن امید آمد و با امید بقا آمد و با بقا امکان تعریف داستان آمد، آموزش درس، کمک به دیگران برای یافتن معنای خودشان."),
            StoryParagraph("And so ended the second part of the story of Man's Search for Meaning, with the beginning of the third stage, with the discovery that would change everything, with the meaning that would save Frankl's life and the lives of millions.", "و اینگونه بخش دوم داستان انسان در جستجوی معنا با آغاز مرحله سوم، با کشفی که همه چیز را تغییر می‌داد، با معنایی که زندگی فرانکل و زندگی میلیون‌ها را نجات می‌داد، به پایان رسید.")
        )
    )

    private fun chapter3() = StoryChapter(
        number = 3, title = "The Inner Life", titlePersian = "زندگی درونی",
        paragraphs = listOf(
            StoryParagraph("Frankl observed, in the camp, that the prisoners who survived were not always the strongest, not always the healthiest, not always the most fortunate. The prisoners who survived were those who had a rich inner life.", "فرانکل در اردوگاه مشاهده کرد که زندانیانی که زنده می‌ماندند همیشه قوی‌ترین نبودند، همیشه سالم‌ترین نبودند، همیشه خوش‌شانس‌ترین نبودند. زندانیانی که زنده می‌ماندند کسانی بودند که زندگی درونی غنی داشتند."),
            StoryParagraph("The Nazis could take everything external: could take clothes, could take food, could take names, could take bodies. But they could not take the inner life, could not take thoughts, could not take memories, could not take love.", "نازی‌ها می‌توانستند هر چیز بیرونی را بگیرند: می‌توانستند لباس بگیرند، غذا بگیرند، نام بگیرند، بدن بگیرند. اما نمی‌توانستند زندگی درونی را بگیرند، نمی‌توانستند اندیشه‌ها را بگیرند، نمی‌توانستند خاطرات را بگیرند، نمی‌توانستند عشق را بگیرند."),
            StoryParagraph("And it was this inner life that saved the survivors, that kept them human, that gave them a reason to continue when every external reason had been taken away.", "و این زندگی درونی بود که بازماندگان را نجات می‌داد، انسان نگهشان می‌داشت، دلیلی برای ادامه دادن می‌داد وقتی هر دلیل بیرونی گرفته شده بود."),
            StoryParagraph("Frankl himself had a rich inner life, had a life of the mind, had a life of love, had a life that no one could touch. Even in the camp, even in the worst moments, he could retreat into this life and find refuge.", "خود فرانکل زندگی درونی غنی داشت، زندگی ذهن داشت، زندگی عشق داشت، زندگی‌ای داشت که هیچ‌کس نمی‌توانست لمسش کند. حتی در اردوگاه، حتی در بدترین لحظه‌ها، می‌توانست به این زندگی عقب‌نشینی کند و پناه بیابد."),
            StoryParagraph("He would think of his wife, think of her face, think of her voice, think of her love. And in these thoughts, he would find strength, would find hope, would find the will to continue.", "به همسرش فکر می‌کرد، به چهره‌اش، به صدایش، به عشقش. و در این اندیشه‌ها قوت می‌یافت، امید می‌یافت، اراده ادامه دادن می‌یافت."),
            StoryParagraph("He would think of his work, think of the book he had written, think of the book he still wanted to write. And in these thoughts, he would find purpose, would find meaning, would find a reason to survive.", "به کارش فکر می‌کرد، به کتابی که نوشته بود، به کتابی که هنوز می‌خواست بنویسد. و در این اندیشه‌ها هدف می‌یافت، معنا، دلیلی برای زنده ماندن."),
            StoryParagraph("He would think of the future, think of the day when he would be free, think of the life he would build after the war. And in these thoughts, he would find hope, would find faith, would find the courage to continue.", "به آینده فکر می‌کرد، به روزی که آزاد می‌شد، به زندگی‌ای که پس از جنگ می‌ساخت. و در این اندیشه‌ها امید می‌یافت، ایمان، شجاعت ادامه دادن."),
            StoryParagraph("And so Frankl learned that the inner life was the last refuge, was the final freedom, was the one thing that no prison could take, no torture could destroy, no death could end.", "و اینگونه فرانکل آموخت که زندگی درونی آخرین پناه بود، آزادی نهایی، تنها چیزی که هیچ زندانی نمی‌توانست بگیرد، هیچ شکنجه‌ای نمی‌توانست نابود کند، هیچ مرگی نمی‌توانست پایان دهد."),
            StoryParagraph("And he observed this in other prisoners, observed that those with rich inner lives survived better, observed that those who could retreat into themselves endured longer, observed that inner wealth was more valuable than outer strength.", "و این را در زندانیان دیگر مشاهده کرد، مشاهده کرد کسانی با زندگی‌های درونی غنی بهتر زنده می‌ماندند، مشاهده کرد کسانی که می‌توانستند به خودشان عقب‌نشینی کنند بیشتر دوام می‌آوردند، مشاهده کرد ثروت درونی ارزشمندتر از قوت بیرونی بود."),
            StoryParagraph("He noticed that artists, writers, philosophers, priests, and others with rich inner lives survived at higher rates than ordinary people, than laborers, than those who had only known external realities.", "متوجه شد هنرمندان، نویسندگان، فیلسوفان، کاهنان و دیگرانی با زندگی‌های درونی غنی با نرخ بالاتری از مردم معمولی، کارگران، کسانی که تنها واقعیت‌های بیرونی را می‌شناختند، زنده می‌ماندند."),
            StoryParagraph("He noticed that those who could dream, who could imagine, who could remember, who could hope, survived better than those who could only see the present, only see the suffering, only see the horror.", "متوجه شد کسانی که می‌توانستند رؤیا ببینند، تصور کنند، به یاد آورند، امیدوار باشند، بهتر از کسانی که تنها حال را می‌دیدند، تنها رنج را، تنها وحشت را، زنده می‌ماندند."),
            StoryParagraph("And he noticed that those who had something to live for, whether a person or a project or a faith, survived better than those who had nothing, than those who had given up, than those who had lost all hope.", "و متوجه شد کسانی که چیزی برای زیستن داشتند، چه شخصی یا پروژه‌ای یا ایمانی، بهتر از کسانی که هیچ نداشتند، از کسانی که تسلیم شده بودند، از کسانی که تمام امید را از دست داده بودند، زنده می‌ماندند."),
            StoryParagraph("And so Frankl formulated his deepest insight, an insight that would change psychology forever: human beings are not primarily driven by pleasure, not primarily driven by power, but primarily driven by meaning.", "و اینگونه فرانکل عمیق‌ترین بصیرت خود را صورت‌بندی کرد، بصیرتی که روان‌شناسی را برای همیشه تغییر می‌داد: انسان‌ها در درجه اول به‌واسطه لذت رانده نمی‌شوند، به‌واسطه قدرت رانده نمی‌شوند، بلکه به‌واسطه معنا رانده می‌شوند."),
            StoryParagraph("Human beings can endure incredible suffering, can endure incredible deprivation, can endure incredible pain, if they have a meaning, if they have a purpose, if they have a why.", "انسان‌ها می‌توانند رنج باورنکردنی را تحمل کنند، محرومیت باورنکردنی، درد باورنکردنی، اگر معنایی داشته باشند، هدفی، چرایی‌ای."),
            StoryParagraph("But human beings cannot endure even mild suffering, cannot endure even minor deprivation, cannot endure even small pain, if they have no meaning, no purpose, no why.", "اما انسان‌ها نمی‌توانند حتی رنج خفیف را تحمل کنند، محرومیت جزئی، درد کوچک، اگر معنایی نداشته باشند، هدفی، چرایی‌ای."),
            StoryParagraph("And so Frankl survived, survived because he had meaning, survived because he had his wife, survived because he had his work, survived because he had his faith, survived because he had something to live for.", "و اینگونه فرانکل زنده ماند، چون معنا داشت زنده ماند، چون همسرش را داشت زنده ماند، چون کارش را داشت زنده ماند، چون ایمانش را داشت زنده ماند، چون چیزی برای زیستن داشت زنده ماند."),
            StoryParagraph("And in surviving, in finding meaning, in refusing to give up, Frankl discovered something that would change the world: that meaning was not given but chosen, not received but created, not imposed but found.", "و در زنده ماندن، در یافتن معنا، در امتناع از تسلیم شدن، فرانکل چیزی کشف کرد که جهان را تغییر می‌داد: که معنا داده نمی‌شود بلکه برگزیده می‌شود، دریافت نمی‌شود بلکه آفریده می‌شود، تحمیل نمی‌شود بلکه یافته می‌شود."),
            StoryParagraph("And so ended the third part of the story of Man's Search for Meaning, with the description of the inner life, with the discovery of the will to meaning, with the insight that would change everything.", "و اینگونه بخش سوم داستان انسان در جستجوی معنا با توصیف زندگی درونی، با کشف اراده به معنا، با بصیرتی که همه چیز را تغییر می‌داد، به پایان رسید."),
            StoryParagraph("For the story of Frankl was not merely the story of a man who survived a camp, but the story of a man who discovered the deepest truth of human existence, a truth that had been hidden, a truth that would set humanity free.", "زیرا داستان فرانکل تنها داستان مردی نبود که از اردوگاهی جان به سلامت برد، بلکه داستان مردی بود که عمیق‌ترین حقیقت وجود انسانی را کشف کرد، حقیقتی که پنهان شده بود، حقیقتی که بشریت را آزاد می‌کرد."),
            StoryParagraph("And so the story continued, as stories must, toward the elaboration of this truth, toward the application of this insight, toward the therapy that would be born from this discovery.", "و اینگونه داستان ادامه یافت، همان‌طور که داستان‌ها باید، به سمت بسط این حقیقت، به سمت کاربرد این بصیرت، به سمت درمانی که از این کشف زاده می‌شد."),
            StoryParagraph("And so ended the third part of the story of Man's Search for Meaning, with the inner life described, with the will to meaning discovered, with the therapy that would change the world about to be described.", "و اینگونه بخش سوم داستان انسان در جستجوی معنا با زندگی درونی توصیف شده، با اراده به معنا کشف شده، با درمانی که جهان را تغییر می‌داد در شرف توصیف، به پایان رسید."),
            StoryParagraph("The outer life was hell, was horror, was suffering beyond description. But the inner life was free, was rich, was full of meaning. And in this inner freedom, in this inner wealth, in this inner meaning, there was hope.", "زندگی بیرونی جهنم بود، وحشت بود، رنجی فراتر از توصیف. اما زندگی درونی آزاد بود، غنی بود، پر از معنا. و در این آزادی درونی، در این ثروت درونی، در این معنای درونی، امیدی بود."),
            StoryParagraph("And so ended the third part of the story of Man's Search for Meaning, with the discovery that inner freedom is the last and greatest freedom, with the insight that would change Frankl's life and the lives of millions.", "و اینگونه بخش سوم داستان انسان در جستجوی معنا با کشف اینکه آزادی درونی آخرین و بزرگ‌ترین آزادی است، با بصیرتی که زندگی فرانکل و زندگی میلیون‌ها را تغییر می‌داد، به پایان رسید.")
        )
    )

    private fun chapter4() = StoryChapter(
        number = 4, title = "Logotherapy", titlePersian = "لوگوتراپی",
        paragraphs = listOf(
            StoryParagraph("After the war, Frankl returned to Vienna, returned to his work, returned to his life. But he was not the same, could not be the same, would never be the same.", "پس از جنگ، فرانکل به وین بازگشت، به کارش بازگشت، به زندگی‌اش بازگشت. اما همان نبود، نمی‌توانست همان باشد، هرگز همان نمی‌شد."),
            StoryParagraph("He had lost everything: his wife, his parents, his home, his possessions. He had lost everyone he loved. He had seen horrors that no human being should ever have to see.", "او همه چیز را از دست داده بود: همسرش، والدینش، خانه‌اش، دارایی‌هایش. هر کسی که دوستش داشت را از دست داده بود. وحشت‌هایی دیده بود که هیچ انسانی نباید هرگز مجبور به دیدنش باشد."),
            StoryParagraph("But he had also gained something, gained something that could not be measured, could not be quantified, could not be taken away. He had gained an understanding of the human soul, an understanding that only suffering could give.", "اما چیزی هم به دست آورده بود، چیزی که نمی‌شد اندازه‌گیری کرد، نمی‌شد کمّی کرد، نمی‌شد گرفت. درکی از روح انسانی به دست آورده بود، درکی که تنها رنج می‌توانست بدهد."),
            StoryParagraph("And out of this understanding, out of this suffering, out of this experience, Frankl created a new therapy, a therapy based on meaning, a therapy that would help human beings to find their own meaning, their own purpose, their own why.", "و از این درک، از این رنج، از این تجربه، فرانکل درمانی نوین آفرید، درمانی مبتنی بر معنا، درمانی که به انسان‌ها کمک می‌کرد معنای خودشان را بیابند، هدف خودشان، چرایی خودشان."),
            StoryParagraph("He called this therapy logotherapy, from the Greek word logos, which means meaning. Logotherapy was not about pleasure, was not about power, was about meaning, was about helping human beings to find the meaning in their lives.", "این درمان را لوگوتراپی نامید، از کلمه یونانی لوگوس که یعنی معنا. لوگوتراپی درباره لذت نبود، درباره قدرت نبود، درباره معنا بود، درباره کمک به انسان‌ها برای یافتن معنا در زندگی‌شان بود."),
            StoryParagraph("The premise of logotherapy was simple, was profound, was revolutionary: human beings are primarily motivated by the will to meaning, by the desire to find meaning in their lives, by the need to have a reason to live.", "مقدمه لوگوتراپی ساده بود، عمیق، انقلابی: انسان‌ها در درجه اول توسط اراده به معنا برانگیخته می‌شوند، توسط میل به یافتن معنا در زندگی‌شان، توسط نیاز به دلیلی برای زیستن."),
            StoryParagraph("Freud had said that human beings were motivated by the will to pleasure. Adler had said that human beings were motivated by the will to power. Frankl said that human beings were motivated by the will to meaning.", "فروید گفته بود انسان‌ها توسط اراده به لذت برانگیخته می‌شوند. آدلر گفته بود انسان‌ها توسط اراده به قدرت برانگیخته می‌شوند. فرانکل گفت انسان‌ها توسط اراده به معنا برانگیخته می‌شوند."),
            StoryParagraph("And Frankl had evidence for this claim, evidence that no other psychologist could match, evidence that came from the worst laboratory in the world, from the camp, from the place where meaning was the only thing that could save you.", "و فرانکل برای این ادعا شاهدی داشت، شاهدی که هیچ روان‌شناس دیگری نمی‌توانست همتایش باشد، شاهدی که از بدترین آزمایشگاه جهان می‌آمد، از اردوگاه، از جایی که معنا تنها چیزی بود که می‌توانست نجاتت دهد."),
            StoryParagraph("For in the camp, Frankl had seen that those with meaning survived and those without meaning died, had seen that the will to meaning was stronger than the will to pleasure, was stronger than the will to power, was the deepest drive of the human soul.", "زیرا در اردوگاه، فرانکل دیده بود کسانی با معنا زنده می‌ماندند و کسانی بدون معنا می‌مردند، دیده بود اراده به معنا قوی‌تر از اراده به لذت است، قوی‌تر از اراده به قدرت، عمیق‌ترین رانه روح انسانی."),
            StoryParagraph("And so Frankl built his therapy on this foundation, built it on meaning, built it on the discovery that human beings could endure anything if they had a why, built it on the truth that no one could take meaning away from you.", "و اینگونه فرانکل درمانش را بر این بنیاد بنا کرد، بر معنا بنا کرد، بر کشف اینکه انسان‌ها می‌توانند هر چیزی را تحمل کنند اگر چرایی داشته باشند بنا کرد، بر حقیقت اینکه هیچ‌کس نمی‌تواند معنا را از تو بگیرد بنا کرد."),
            StoryParagraph("Logotherapy had three main principles. The first was that life has meaning under all circumstances, even the most miserable ones. There is no situation in which meaning cannot be found.", "لوگوتراپی سه اصل اصلی داشت. نخست اینکه زندگی در همه شرایط معنا دارد، حتی در بدترین‌ها. هیچ موقعیتی نیست که در آن معنا یافته نشود."),
            StoryParagraph("The second principle was that our main motivation for living is our will to find meaning in life. We do not live for pleasure, we do not live for power, we live for meaning, we live for purpose, we live for a reason.", "اصل دوم اینکه انگیزه اصلی ما برای زندگی اراده‌مان به یافتن معنا در زندگی است. برای لذت زندگی نمی‌کنیم، برای قدرت زندگی نمی‌کنیم، برای معنا زندگی می‌کنیم، برای هدف، برای دلیلی."),
            StoryParagraph("The third principle was that we have the freedom to find meaning in what we do, in what we experience, and in the attitude we take toward suffering. We cannot always choose our circumstances, but we can always choose our response.", "اصل سوم اینکه ما آزادی یافتن معنا را در آنچه می‌کنیم، در آنچه تجربه می‌کنیم، و در نگرشی که به رنج می‌گیریم داریم. همیشه نمی‌توانیم شرایطمان را انتخاب کنیم، اما همیشه می‌توانیم پاسخمان را انتخاب کنیم."),
            StoryParagraph("And so logotherapy was not about avoiding suffering, was not about eliminating pain, was not about achieving happiness. Logotherapy was about finding meaning, was about discovering purpose, was about living with a why.", "و اینگونه لوگوتراپی درباره اجتناب از رنج نبود، درباره حذف درد نبود، درباره رسیدن به خوشبختی نبود. لوگوتراپی درباره یافتن معنا بود، کشف هدف، زندگی کردن با چرایی."),
            StoryParagraph("Frankl practiced logotherapy for decades, helped thousands of patients, wrote dozens of books, taught at universities around the world. And everywhere he went, he carried the lessons of the camp, the lessons of suffering, the lessons of meaning.", "فرانکل دهه‌ها لوگوتراپی را عمل کرد، به هزاران بیمار کمک کرد، ده‌ها کتاب نوشت، در دانشگاه‌های سراسر جهان تدریس کرد. و هر جا می‌رفت، درس‌های اردوگاه را با خود می‌برد، درس‌های رنج، درس‌های معنا."),
            StoryParagraph("And everywhere he went, he taught the same truth: that meaning is not given but found, not received but created, not imposed but chosen. And that this meaning, this found, created, chosen meaning, is what makes life worth living.", "و هر جا می‌رفت، همان حقیقت را می‌آموخت: که معنا داده نمی‌شود بلکه یافته می‌شود، دریافت نمی‌شود بلکه آفریده می‌شود، تحمیل نمی‌شود بلکه برگزیده می‌شود. و این معنا، این معنای یافته، آفریده، برگزیده، چیزی است که زندگی را ارزش زیستن می‌کند."),
            StoryParagraph("And so ended the fourth part of the story of Man's Search for Meaning, with the creation of logotherapy, with the three principles of meaning, with the therapy that would change the world.", "و اینگونه بخش چهارم داستان انسان در جستجوی معنا با آفرینش لوگوتراپی، با سه اصل معنا، با درمانی که جهان را تغییر می‌داد، به پایان رسید."),
            StoryParagraph("For logotherapy was not merely a therapy, not merely a method, not merely a technique. Logotherapy was a philosophy, was a way of life, was a set of principles that could guide anyone through any difficulty.", "زیرا لوگوتراپی تنها یک درمان نبود، تنها یک روش نبود، تنها یک تکنیک نبود. لوگوتراپی یک فلسفه بود، یک شیوه زندگی، مجموعه‌ای از اصول که می‌توانست هر کسی را در هر دشواری راهنمایی کند."),
            StoryParagraph("And so the story continued, as stories must, toward the application of logotherapy, toward the therapy in practice, toward the healing that would come from finding meaning in suffering.", "و اینگونه داستان ادامه یافت، همان‌طور که داستان‌ها باید، به سمت کاربرد لوگوتراپی، به سمت درمان در عمل، به سمت شفایی که از یافتن معنا در رنج می‌آمد."),
            StoryParagraph("And so ended the fourth part of the story of Man's Search for Meaning, with the therapy created, with the principles described, with the healing that would change the world about to be described.", "و اینگونه بخش چهارم داستان انسان در جستجوی معنا با درمان آفریده شده، با اصول توصیف شده، با شفایی که جهان را تغییر می‌داد در شرف توصیف، به پایان رسید."),
            StoryParagraph("The therapy was born, was born from suffering, was born from meaning, was born from the deepest truth of human existence. And this therapy, this truth, this meaning, would be Frankl's gift to the world.", "درمان زاده شد، از رنج زاده شد، از معنا زاده شد، از عمیق‌ترین حقیقت وجود انسانی زاده شد. و این درمان، این حقیقت، این معنا، هدیه فرانکل به جهان می‌بود."),
            StoryParagraph("And so ended the fourth part of the story of Man's Search for Meaning, with the therapy created, with the principles established, with the healing that would change the world about to unfold.", "و اینگونه بخش چهارم داستان انسان در جستجوی معنا با درمان آفریده شده، با اصول برقرار شده، با شفایی که جهان را تغییر می‌داد در شرف باز شدن، به پایان رسید."),
            StoryParagraph("And so the story continued, as all stories must, toward the application of this therapy, toward the cases that would prove its power, toward the lives that would be transformed by finding meaning.", "و اینگونه داستان ادامه یافت، همان‌طور که همه داستان‌ها باید، به سمت کاربرد این درمان، به سمت مواردی که قدرتش را ثابت می‌کردند، به سمت زندگی‌هایی که با یافتن معنا دگرگون می‌شدند."),
            StoryParagraph("And so ended the fourth part of the story of Man's Search for Meaning, with the therapy born, with the principles laid out, with the cases that would prove everything about to be described.", "و اینگونه بخش چهارم داستان انسان در جستجوی معنا با درمان زاده شده، با اصول چیده شده، با مواردی که همه چیز را ثابت می‌کردند در شرف توصیف، به پایان رسید.")
        )
    )

    private fun chapter5() = StoryChapter(
        number = 5, title = "The Case of the Grieving Doctor", titlePersian = "مورد پزشک سوگوار",
        paragraphs = listOf(
            StoryParagraph("One day, a patient came to Frankl, a doctor who had lost his wife, a doctor who could not stop grieving, a doctor who could not find a reason to continue living.", "یک روز، بیماری به نزد فرانکل آمد، پزشکی که همسرش را از دست داده بود، پزشکی که نمی‌توانست از سوگ دست بکشد، پزشکی که نمی‌توانست دلیلی برای ادامه زندگی بیابد."),
            StoryParagraph("The doctor was in despair, was in the depths of a depression that seemed bottomless, was in a state of suffering that he believed could never end. He had loved his wife more than anything in the world, and now she was gone.", "پزشک در ناامیدی بود، در اعماق افسردگی‌ای که بی‌پایان به نظر می‌رسید، در وضعیتی از رنج که باور داشت هرگز نمی‌تواند پایان یابد. همسرش را بیشتر از هر چیزی در جهان دوست داشت و اکنون او رفته بود."),
            StoryParagraph("Frankl listened to the doctor, listened to his grief, listened to his despair, listened to his belief that life had lost all meaning. And Frankl did not try to comfort him, did not try to cheer him up, did not try to minimize his pain.", "فرانکل به پزشک گوش داد، به سوگش گوش داد، به ناامیدی‌اش، به باورش به اینکه زندگی تمام معنا را از دست داده. و فرانکل تلاش نکرد تسلی‌اش دهد، تلاش نکرد شادش کند، تلاش نکرد دردمندی‌اش را کم‌اهمیت جلوه دهد."),
            StoryParagraph("Instead, Frankl asked him a question, a simple question, a question that would transform the doctor's suffering into meaning, a question that would change his life.", "در عوض، فرانکل پرسشی از او پرسید، پرسشی ساده، پرسشی که رنج پزشک را به معنا تبدیل می‌کرد، پرسشی که زندگی‌اش را تغییر می‌داد."),
            StoryParagraph("Frankl asked: What would have happened if you had died first, and your wife had been left alone to grieve for you? What would she have suffered? How much pain would she have had to endure?", "فرانکل پرسید: اگر تو اول مرده بودی و همسرت برای تو تنها می‌ماند تا سوگوار شود چه می‌شد؟ او چه رنجی می‌کشید؟ چه اندازه درد باید تحمل می‌کرد؟"),
            StoryParagraph("The doctor was struck by the question, was struck by the thought, was struck by the realization that his suffering could be seen in a different light. He thought about his wife, thought about her love for him, thought about the pain she would have felt.", "پزشک توسط این پرسش ضربه خورد، توسط این اندیشه، توسط این درک که رنجش می‌توانست از منظری متفاوت دیده شود. به همسرش فکر کرد، به عشقش به او، به دردی که او می‌کشید."),
            StoryParagraph("And then he understood. He understood that his suffering was a sacrifice, was a price he was paying, was a cost he was bearing so that his wife would not have to. He was suffering so that she would not have to suffer.", "و سپس فهمید. فهمید که رنجش قربانی بود، بهایی بود که می‌پرداخت، هزینه‌ای بود که تحمل می‌کرد تا همسرش مجبور نباشد. او رنج می‌کشید تا همسرش مجبور نباشد رنج بکشد."),
            StoryParagraph("In that moment, the doctor's suffering was transformed. It was no longer meaningless, was no longer pointless, was no longer unbearable. It was a gift, was a sacrifice, was an act of love that gave his pain a meaning.", "در آن لحظه، رنج پزشک دگرگون شد. دیگر بی‌معنا نبود، بی‌هدف نبود، غیرقابل تحمل نبود. هدیه بود، قربانی بود، عملی از عشق که به دردمندی‌اش معنا می‌بخشید."),
            StoryParagraph("The doctor left Frankl's office a different man. His suffering had not ended, had not diminished, had not disappeared. But it had been transformed, had been given meaning, had been turned from a curse into a gift.", "پزشک دفتر فرانکل را مردی متفاوت ترک کرد. رنجش تمام نشده بود، کم نشده بود، ناپدید نشده بود. اما دگرگون شده بود، معنا یافته بود، از نفرین به هدیه تبدیل شده بود."),
            StoryParagraph("This was the power of logotherapy, this was the power of meaning, this was the power of finding purpose in the midst of suffering. Frankl had not changed the doctor's situation. He had changed the doctor's response to it.", "این قدرت لوگوتراپی بود، قدرت معنا، قدرت یافتن هدف در میان رنج. فرانکل وضعیت پزشک را تغییر نداده بود. پاسخ او به آن را تغییر داده بود."),
            StoryParagraph("And so Frankl demonstrated, in this case and in thousands of others, that the last of the human freedoms was the freedom to choose one's attitude in any given set of circumstances, the freedom to find meaning in any situation.", "و اینگونه فرانکل در این مورد و هزاران مورد دیگر نشان داد که آخرین آزادی‌های انسانی آزادی انتخاب نگرش در هر مجموعه شرایط است، آزادی یافتن معنا در هر موقعیت."),
            StoryParagraph("And so ended the fifth part of the story of Man's Search for Meaning, with the case of the grieving doctor, with the transformation of suffering into meaning, with the therapy that would change the world.", "و اینگونه بخش پنجم داستان انسان در جستجوی معنا با مورد پزشک سوگوار، با تبدیل رنج به معنا، با درمانی که جهان را تغییر می‌داد، به پایان رسید."),
            StoryParagraph("For the story of the grieving doctor was not merely the story of one man, not merely the story of one case, not merely the story of one session. It was the story of every human being who has ever suffered and who has needed to find meaning in that suffering.", "زیرا داستان پزشک سوگوار تنها داستان یک مرد نبود، تنها داستان یک مورد نبود، تنها داستان یک جلسه نبود. داستان هر انسانی بود که هرگز رنج کشیده و نیاز داشته در آن رنج معنا بیابد."),
            StoryParagraph("And so the story continued, as stories must, toward the elaboration of this therapy, toward the demonstration of its power, toward the proof that meaning could be found in any situation.", "و اینگونه داستان ادامه یافت، همان‌طور که داستان‌ها باید، به سمت بسط این درمان، به سمت نمایش قدرتش، به سمت اثبات اینکه معنا در هر موقعیتی می‌تواند یافته شود."),
            StoryParagraph("And so ended the fifth part of the story of Man's Search for Meaning, with the case described, with the transformation demonstrated, with the therapy that would change the world about to be further explored.", "و اینگونه بخش پنجم داستان انسان در جستجوی معنا با مورد توصیف شده، با دگرگونی نمایش داده شده، با درمانی که جهان را تغییر می‌داد در شرف بیشتر کاوش شدن، به پایان رسید."),
            StoryParagraph("The doctor's suffering had not disappeared, but it had been transformed. And this transformation, this meaning, this discovery, was what Frankl offered to all who came to him, was what he had learned in the camp, was what he gave to the world.", "رنج پزشک ناپدید نشده بود اما دگرگون شده بود. و این دگرگونی، این معنا، این کشف، چیزی بود که فرانکل به همه کسانی که به نزدش می‌آمدند عرضه می‌کرد، چیزی بود که در اردوگاه آموخته بود، چیزی بود که به جهان می‌داد."),
            StoryParagraph("And so ended the fifth part of the story of Man's Search for Meaning, with the transformation of suffering described, with the power of meaning demonstrated, with the therapy that would change millions of lives finally understood.", "و اینگونه بخش پنجم داستان انسان در جستجوی معنا با دگرگونی رنج توصیف شده، با قدرت معنا نمایش داده شده، با درمانی که زندگی میلیون‌ها را تغییر می‌داد بالاخره فهمیده شده، به پایان رسید."),
            StoryParagraph("For the doctor had found meaning, had found purpose, had found a reason to continue living. And in finding meaning, he had found hope. And in finding hope, he had found life. And in finding life, he had found everything.", "زیرا پزشک معنا یافته بود، هدف یافته بود، دلیلی برای ادامه زندگی یافته بود. و در یافتن معنا، امید یافته بود. و در یافتن امید، زندگی یافته بود. و در یافتن زندگی، همه چیز یافته بود."),
            StoryParagraph("And so the fifth part ended, and the sixth began, with the final lessons of the camp, with the ultimate truth of human existence, with the meaning that would save humanity from despair.", "و اینگونه بخش پنجم پایان یافت و ششم آغاز شد، با درس‌های نهایی اردوگاه، با حقیقت نهایی وجود انسانی، با معنایی که بشریت را از ناامیدی نجات می‌داد."),
            StoryParagraph("And so the story continued, as all stories must, toward the ultimate meaning, toward the deepest truth, toward the light that could shine even in the darkest of places.", "و اینگونه داستان ادامه یافت، همان‌طور که همه داستان‌ها باید، به سمت معنای نهایی، به سمت عمیق‌ترین حقیقت، به سمت نوری که می‌توانست حتی در تاریک‌ترین مکان‌ها بدرخشد."),
            StoryParagraph("And so ended the fifth part of the story of Man's Search for Meaning, with the case complete, with the therapy demonstrated, with the truth that would save humanity about to be fully revealed.", "و اینگونه بخش پنجم داستان انسان در جستجوی معنا با مورد کامل، با درمان نمایش داده شده، با حقیقتی که بشریت را نجات می‌داد در شرف آشکار شدن کامل، به پایان رسید.")
        )
    )

    private fun chapter6() = StoryChapter(
        number = 6, title = "The Tragic Optimism", titlePersian = "خوش‌بینی تراژیک",
        paragraphs = listOf(
            StoryParagraph("And so we come to the final lesson, to the deepest truth, to the meaning that Frankl found in the camp and that he spent the rest of his life teaching to the world.", "و اینگونه به درس نهایی می‌رسیم، به عمیق‌ترین حقیقت، به معنایی که فرانکل در اردوگاه یافت و باقی عمرش را صرف آموزشش به جهان کرد."),
            StoryParagraph("Frankl called this lesson tragic optimism, called it the ability to say yes to life in spite of everything, called it the affirmation of life in the face of suffering, guilt, and death.", "فرانکل این درس را خوش‌بینی تراژیک نامید، توانایی گفتن آری به زندگی علی‌رغم همه چیز، تأیید زندگی در برابر رنج، گناه و مرگ."),
            StoryParagraph("Tragic optimism was not naive optimism, was not the belief that everything would be fine, was not the denial of suffering, was not the pretense that pain did not exist.", "خوش‌بینی تراژیک خوش‌بینی ساده‌لوحانه نبود، باور به اینکه همه چیز خوب می‌شود نبود، انکار رنج نبود، تظاهر به اینکه درد وجود ندارد نبود."),
            StoryParagraph("Tragic optimism was the deepest form of optimism, was the only honest form of optimism, was the optimism that could survive contact with reality, was the optimism that could face the truth and still affirm life.", "خوش‌بینی تراژیک عمیق‌ترین شکل خوش‌بینی بود، تنها شکل صادقانه خوش‌بینی، خوش‌بینی‌ای که می‌توانست با واقعیت تماس پیدا کند و جان به سلامت ببرد، خوش‌بینی‌ای که می‌توانست با حقیقت روبرو شود و با این حال زندگی را تأیید کند."),
            StoryParagraph("For Frankl had seen the worst that human beings could do to each other, had seen the worst that human beings could suffer, had seen the depths of cruelty and the heights of courage, had seen everything.", "زیرا فرانکل بدترین چیزی که انسان‌ها می‌توانند با یکدیگر بکنند را دیده بود، بدترین چیزی که می‌توانند تحمل کنند، عمق بی‌رحمی و اوج شجاعت، همه چیز را دیده بود."),
            StoryParagraph("And yet, having seen everything, having suffered everything, having lost everything, Frankl still said yes to life. Frankl still believed that life was worth living. Frankl still found meaning in existence.", "و با این حال، پس از دیدن همه چیز، تحمل همه چیز، از دست دادن همه چیز، فرانکل هنوز به زندگی آری می‌گفت. هنوز باور داشت زندگی ارزش زیستن دارد. هنوز در هستی معنا می‌یافت."),
            StoryParagraph("This was tragic optimism, was the affirmation of life in the face of everything that would deny it, was the yes that is spoken even when the answer is no, was the hope that survives even in the darkest of nights.", "این خوش‌بینی تراژیک بود، تأیید زندگی در برابر هر چیزی که انکارش می‌کرد، آری‌ای که حتی وقتی پاسخ نه است گفته می‌شود، امیدی که حتی در تاریک‌ترین شب‌ها جان به سلامت می‌برد."),
            StoryParagraph("And Frankl believed that this tragic optimism could be taught, could be learned, could be practiced. He believed that anyone could find meaning in their lives, could find purpose in their suffering, could find hope even in despair.", "و فرانکل باور داشت این خوش‌بینی تراژیک می‌توانست آموزش داده شود، یاد گرفته شود، تمرین شود. باور داشت هر کسی می‌توانست در زندگی‌اش معنا بیابد، در رنجش هدف، حتی در ناامیدی امید."),
            StoryParagraph("For meaning was not something that some people had and others did not. Meaning was something that everyone could find, was something that everyone could create, was something that everyone could choose.", "زیرا معنا چیزی نبود که برخی داشته باشند و برخی نداشته باشند. معنا چیزی بود که هر کسی می‌توانست بیابد، هر کسی می‌توانست بیافریند، هر کسی می‌توانست برگزیند."),
            StoryParagraph("And the ways to find meaning were three, according to Frankl. The first was through work, through creating something, through contributing to the world, through doing something that mattered.", "و راه‌های یافتن معنا به گفته فرانکل سه بود. نخست از طریق کار، از طریق آفریدن چیزی، از طریق سهم داشتن در جهان، از طریق انجام کاری که اهمیت دارد."),
            StoryParagraph("The second was through love, through experiencing something, through encountering someone, through connecting with another human being in a way that transformed both of you.", "دوم از طریق عشق، از طریق تجربه کردن چیزی، از طریق روبرو شدن با کسی، از طریق ارتباط با انسانی دیگر به شیوه‌ای که هر دو شما را دگرگون می‌کرد."),
            StoryParagraph("The third was through suffering, through the attitude we take toward unavoidable suffering, through the meaning we find in the pain that we cannot escape, through the dignity with which we bear what cannot be changed.", "سوم از طریق رنج، از طریق نگرشی که نسبت به رنج اجتناب‌ناپذیر می‌گیریم، از طریق معنایی که در دردی که نمی‌توانیم از آن بگریزیم می‌یابیم، از طریق کرامتی که با آن آنچه تغییرناپذیر است را تحمل می‌کنیم."),
            StoryParagraph("And so Frankl offered hope to humanity, offered a way to live with suffering, offered a way to find meaning in any situation, offered a way to say yes to life even when life seemed to say no.", "و اینگونه فرانکل به بشریت امید عرضه کرد، راهی برای زندگی با رنج، راهی برای یافتن معنا در هر موقعیت، راهی برای گفتن آری به زندگی حتی وقتی زندگی نه می‌گفت."),
            StoryParagraph("For Frankl had learned, in the camp, in the worst place on earth, that meaning could be found anywhere. Had learned that the human spirit could triumph over any circumstance. Had learned that no one could take meaning away from you.", "زیرا فرانکل در اردوگاه، در بدترین جای زمین، آموخته بود معنا در همه‌جا می‌تواند یافته شود. آموخته بود روح انسانی می‌تواند بر هر شرایطی چیره شود. آموخته بود هیچ‌کس نمی‌تواند معنا را از تو بگیرد."),
            StoryParagraph("And so Frankl gave this gift to the world, gave the gift of meaning, gave the gift of hope, gave the gift of tragic optimism. And the world, in return, gave him what he had always wanted: a chance to help, a chance to teach, a chance to make a difference.", "و اینگونه فرانکل این هدیه را به جهان داد، هدیه معنا، هدیه امید، هدیه خوش‌بینی تراژیک. و جهان در عوض به او آنچه همیشه می‌خواست داد: فرصتی برای کمک، فرصتی برای آموزش، فرصتی برای تفاوت ایجاد کردن."),
            StoryParagraph("And so ended the sixth and final part of the story of Man's Search for Meaning, with the tragic optimism described, with the three ways to find meaning revealed, with the hope that would save humanity finally understood.", "و اینگونه بخش ششم و آخرین داستان انسان در جستجوی معنا با خوش‌بینی تراژیک توصیف شده، با سه راه یافتن معنا آشکار شده، با امیدی که بشریت را نجات می‌داد بالاخره فهمیده شده، به پایان رسید."),
            StoryParagraph("The end.", "پایان."),
            StoryParagraph("But the search remains, remains for every human being, remains for every generation, remains as long as there are human beings who need to find meaning in their lives.", "اما جستجو باقی می‌ماند، برای هر انسانی، برای هر نسلی، تا زمانی که انسان‌هایی باشند که نیاز دارند در زندگی‌شان معنا بیابند."),
            StoryParagraph("And so ended the story of Man's Search for Meaning, not with a conclusion but with a question, not with an answer but with an invitation, not with a comfort but with a challenge.", "و اینگونه داستان انسان در جستجوی معنا پایان یافت، نه با نتیجه‌گیری بلکه با پرسشی، نه با پاسخ بلکه با دعوتی، نه با تسلی بلکه با چالشی."),
            StoryParagraph("The invitation was this: to find your own meaning, to discover your own purpose, to create your own why. And the challenge was this: to live with that meaning, to suffer with that purpose, to die with that why.", "دعوت این بود: معنای خودت را بیاب، هدف خودت را کشف کن، چرایی خودت را بیافرین. و چالش این بود: با آن معنا زندگی کن، با آن هدف رنج بکش، با آن چرایی بمیر."),
            StoryParagraph("For Frankl had shown, in his life and in his work and in his death, that meaning was possible, that hope was possible, that joy was possible, even in the worst of circumstances, even in the camp, even in the gas chamber.", "زیرا فرانکل در زندگی‌اش و در کارش و در مرگش نشان داده بود معنا ممکن است، امید ممکن است، شادی ممکن است، حتی در بدترین شرایط، حتی در اردوگاه، حتی در اتاق گاز."),
            StoryParagraph("And this truth, this discovery, this gift, was what Frankl gave to the world. And the world, having received this gift, was changed forever, was made better, was made more human.", "و این حقیقت، این کشف، این هدیه، چیزی بود که فرانکل به جهان داد. و جهان، پس از دریافت این هدیه، برای همیشه تغییر یافت، بهتر شد، انسانی‌تر شد."),
            StoryParagraph("And so the story of Man's Search for Meaning ended, as all great stories end, with a gift, with a truth, with a meaning that would outlast the story itself.", "و اینگونه داستان انسان در جستجوی معنا پایان یافت، همان‌طور که همه داستان‌های بزرگ پایان می‌یابند، با هدیه‌ای، با حقیقتی، با معنایی که از خود داستان بیشتر دوام می‌آورد."),
            StoryParagraph("The end.", "پایان."),
            StoryParagraph("But the search continues.", "اما جستجو ادامه دارد."),
            StoryParagraph("And so ended the story of Man's Search for Meaning, with the tragic optimism described, with the three ways to find meaning revealed, with the hope that would save humanity finally understood.", "و اینگونه داستان انسان در جستجوی معنا با خوش‌بینی تراژیک توصیف شده، با سه راه یافتن معنا آشکار شده، با امیدی که بشریت را نجات می‌داد بالاخره فهمیده شده، به پایان رسید."),
            StoryParagraph("For Frankl had learned, in the worst place on earth, that life has meaning, that suffering has meaning, that death has meaning, and that this meaning, this discovered, created, chosen meaning, was what made life worth living.", "زیرا فرانکل در بدترین جای زمین آموخته بود زندگی معنا دارد، رنج معنا دارد، مرگ معنا دارد، و این معنا، این معنای کشف‌شده، آفریده، برگزیده، چیزی بود که زندگی را ارزش زیستن می‌کرد."),
            StoryParagraph("And so Frankl lived, lived fully, lived meaningfully, lived with purpose. And in living this way, he taught the world how to live. And in dying, he taught the world how to die. And in both, he taught the world how to find meaning.", "و اینگونه فرانکل زندگی کرد، به تمامی زندگی کرد، معنادار زندگی کرد، با هدف زندگی کرد. و در این شیوه زندگی کردن، به جهان آموخت چطور زندگی کند. و در مردن، به جهان آموخت چطور بمیرد. و در هر دو، به جهان آموخت چطور معنا بیابد."),
            StoryParagraph("And so ended the story of Man's Search for Meaning, with the gift given, with the truth revealed, with the hope that would outlast the story itself.", "و اینگونه داستان انسان در جستجوی معنا با هدیه داده شده، با حقیقت آشکار شده، با امیدی که از خود داستان بیشتر دوام می‌آورد، به پایان رسید."),
            StoryParagraph("The end.", "پایان."),
            StoryParagraph("But the meaning remains.", "اما معنا باقی می‌ماند.")
        )
    )
}